PRAGMA journal_mode=WAL;
PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS meta(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,username TEXT,name TEXT NOT NULL,tier TEXT NOT NULL DEFAULT 'standard',expires INTEGER NOT NULL DEFAULT 0,last_claim INTEGER NOT NULL DEFAULT 0,state TEXT);
CREATE TABLE IF NOT EXISTS trials(user_id INTEGER,kind TEXT,PRIMARY KEY(user_id,kind));
CREATE TABLE IF NOT EXISTS lots(id INTEGER PRIMARY KEY,source TEXT NOT NULL,external_id TEXT NOT NULL,data TEXT NOT NULL,tier TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'free',claimed_by INTEGER,claimed_at INTEGER,UNIQUE(source,external_id));
CREATE TABLE IF NOT EXISTS publications(lot_id INTEGER PRIMARY KEY,chat_id INTEGER NOT NULL,message_id INTEGER NOT NULL,thread_id INTEGER);
CREATE TABLE IF NOT EXISTS jobs(id INTEGER PRIMARY KEY,kind TEXT NOT NULL,payload TEXT NOT NULL,unique_key TEXT UNIQUE,attempts INTEGER NOT NULL DEFAULT 0,next_at INTEGER NOT NULL DEFAULT 0,done INTEGER NOT NULL DEFAULT 0,error TEXT);
CREATE TABLE IF NOT EXISTS invites(link TEXT PRIMARY KEY,user_id INTEGER NOT NULL,chat_id INTEGER NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS members(user_id INTEGER,chat_id INTEGER,PRIMARY KEY(user_id,chat_id));
CREATE TABLE IF NOT EXISTS codes(hash TEXT PRIMARY KEY,tier TEXT NOT NULL,seconds INTEGER NOT NULL,expires INTEGER NOT NULL,max_uses INTEGER NOT NULL,uses INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS redemptions(hash TEXT,user_id INTEGER,PRIMARY KEY(hash,user_id));
CREATE TABLE IF NOT EXISTS orders(id TEXT PRIMARY KEY,user_id INTEGER NOT NULL,tier TEXT NOT NULL,stars INTEGER NOT NULL,seconds INTEGER NOT NULL,created INTEGER NOT NULL,paid INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS payments(charge TEXT PRIMARY KEY,order_id TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS inbox(id INTEGER PRIMARY KEY,data TEXT NOT NULL,done INTEGER NOT NULL DEFAULT 0,error TEXT);
CREATE TABLE IF NOT EXISTS license_keys(key TEXT PRIMARY KEY,owner_id INTEGER NOT NULL,tier TEXT NOT NULL,seconds INTEGER NOT NULL,issued_at INTEGER NOT NULL,activated_at INTEGER,expires INTEGER NOT NULL DEFAULT 0,revoked INTEGER NOT NULL DEFAULT 0,reference TEXT UNIQUE NOT NULL);
